   123→// taskToolInput represents the tool_input structure for the Task tool.
   124→// Used to extract subagent_type and description for descriptive commit messages.
   125→type taskToolInput struct {
   126→	SubagentType string `json:"subagent_type"`
   127→	Description  string `json:"description"`
   128→}
   129→
   130→// ParseSubagentTypeAndDescription extracts subagent_type and description from Task tool_input.
   131→// Returns empty strings if parsing fails or fields are not present.
   132→func ParseSubagentTypeAndDescription(toolInput json.RawMessage) (agentType, description string) {
   133→	if len(toolInput) == 0 {
   134→		return "", ""
   135→	}
   136→
   137→	var input taskToolInput
   138→	if err := json.Unmarshal(toolInput, &input); err != nil {
   139→		return "", ""
   140→	}
   141→
   142→	return input.SubagentType, input.Description
   143→}
   144→
   145→// todoWriteToolInput represents the tool_input structure for the TodoWrite tool.
   146→// Used to extract the todos array which is then passed to strategy.ExtractInProgressTodo.
   147→type todoWriteToolInput struct {
   148→	Todos json.RawMessage `json:"todos"`
   149→}
   150→
   151→// ExtractTodoContentFromToolInput extracts the content of the in-progress todo item from TodoWrite tool_input.
   152→// Falls back to the first pending item if no in-progress item is found.
   153→// Returns empty string if no suitable item is found or JSON is invalid.
   154→//
   155→// This function unwraps the outer tool_input object to extract the todos array,
   156→// then delegates to strategy.ExtractInProgressTodo for the actual parsing logic.
   157→func ExtractTodoContentFromToolInput(toolInput json.RawMessage) string {
   158→	if len(toolInput) == 0 {
   159→		return ""
   160→	}
   161→
   162→	// First extract the todos array from tool_input
   163→	var input todoWriteToolInput
   164→	if err := json.Unmarshal(toolInput, &input); err != nil {
   165→		return ""
   166→	}
   167→
   168→	// Delegate to strategy package for the actual extraction logic
   169→	return strategy.ExtractInProgressTodo(input.Todos)
   170→}
   171→
   172→// ExtractLastCompletedTodoFromToolInput extracts the content of the last completed todo item.
   173→// In PostToolUse[TodoWrite], the tool_input contains the NEW todo list where the
   174→// just-finished work is marked as "completed". The last completed item represents
   175→// the work that was just done.
   176→//
   177→// Returns empty string if no completed items exist or JSON is invalid.
   178→func ExtractLastCompletedTodoFromToolInput(toolInput json.RawMessage) string {
   179→	if len(toolInput) == 0 {
   180→		return ""
   181→	}
   182→
   183→	// First extract the todos array from tool_input
   184→	var input todoWriteToolInput
   185→	if err := json.Unmarshal(toolInput, &input); err != nil {
   186→		return ""
   187→	}
   188→
   189→	// Delegate to strategy package for the actual extraction logic
   190→	return strategy.ExtractLastCompletedTodo(input.Todos)
   191→}
   192→
   193→// CountTodosFromToolInput returns the number of todo items in the TodoWrite tool_input.
   194→// Returns 0 if the JSON is invalid or empty.
   195→//
   196→// This function unwraps the outer tool_input object to extract the todos array,
   197→// then delegates to strategy.CountTodos for the actual count.
   198→func CountTodosFromToolInput(toolInput json.RawMessage) int {
   199→	if len(toolInput) == 0 {
   200→		return 0
   201→	}
   202→
   203→	// First extract the todos array from tool_input
   204→	var input todoWriteToolInput
   205→	if err := json.Unmarshal(toolInput, &input); err != nil {
   206→		return 0
   207→	}
   208→
   209→	// Delegate to strategy package for the actual count
   210→	return strategy.CountTodos(input.Todos)
   211→}
   212→
   213→// logPostTaskHookContext logs the PostToolUse[Task] hook context to the writer
   214→func logPostTaskHookContext(w io.Writer, input *PostTaskHookInput, subagentTranscriptPath string) {
   215→	_, _ = fmt.Fprintln(w, "[entire] PostToolUse[Task] hook invoked")
   216→	_, _ = fmt.Fprintf(w, "  Session ID: %s\n", input.SessionID)
   217→	_, _ = fmt.Fprintf(w, "  Tool Use ID: %s\n", input.ToolUseID)
   218→
   219→	if input.AgentID != "" {
   220→		_, _ = fmt.Fprintf(w, "  Agent ID: %s\n", input.AgentID)
   221→	} else {
   222→		_, _ = fmt.Fprintln(w, "  Agent ID: (none)")
   223→	}
   224→
   225→	_, _ = fmt.Fprintf(w, "  Transcript: %s\n", input.TranscriptPath)
   226→
   227→	if subagentTranscriptPath != "" {
   228→		_, _ = fmt.Fprintf(w, "  Subagent Transcript: %s\n", subagentTranscriptPath)
   229→	} else {
   230→		_, _ = fmt.Fprintln(w, "  Subagent Transcript: (none)")
   231→	}
   232→}
