   967→// handleClaudeCodeSessionEnd handles the SessionEnd hook for Claude Code.
   968→// This fires when the user explicitly closes the session.
   969→// Updates the session state with EndedAt timestamp.
   970→func handleClaudeCodeSessionEnd() error {
   971→	ag, err := GetCurrentHookAgent()
   972→	if err != nil {
   973→		return fmt.Errorf("failed to get agent: %w", err)
   974→	}
   975→
   976→	input, err := ag.ParseHookInput(agent.HookSessionEnd, os.Stdin)
   977→	if err != nil {
   978→		return fmt.Errorf("failed to parse hook input: %w", err)
   979→	}
   980→
   981→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
   982→	logging.Info(logCtx, "session-end",
   983→		slog.String("hook", "session-end"),
   984→		slog.String("hook_type", "agent"),
   985→		slog.String("model_session_id", input.SessionID),
   986→	)
   987→
   988→	entireSessionID := currentSessionIDWithFallback(input.SessionID)
   989→	if entireSessionID == "" {
   990→		return nil // No session to update
   991→	}
   992→
   993→	// Best-effort cleanup - don't block session closure on failure
   994→	if err := markSessionEnded(entireSessionID); err != nil {
   995→		fmt.Fprintf(os.Stderr, "Warning: failed to mark session ended: %v\n", err)
   996→	}
   997→	return nil
   998→}
