   359→// commitWithMetadata commits the session changes with metadata.
   360→func commitWithMetadata() error {
   361→	// Skip on default branch for strategies that don't allow it
   362→	if skip, branchName := ShouldSkipOnDefaultBranchForStrategy(); skip {
   363→		fmt.Fprintf(os.Stderr, "Entire: skipping on branch '%s' - create a feature branch to use Entire tracking\n", branchName)
   364→		return nil // Don't fail the hook, just skip
   365→	}
   366→
   367→	// Get the agent for hook input parsing and session ID transformation
   368→	ag, err := GetCurrentHookAgent()
   369→	if err != nil {
   370→		return fmt.Errorf("failed to get agent: %w", err)
   371→	}
   372→
   373→	// Parse hook input using agent interface
   374→	input, err := ag.ParseHookInput(agent.HookStop, os.Stdin)
   375→	if err != nil {
   376→		return fmt.Errorf("failed to parse hook input: %w", err)
   377→	}
   378→
   379→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
   380→	logging.Info(logCtx, "stop",
   381→		slog.String("hook", "stop"),
   382→		slog.String("hook_type", "agent"),
   383→		slog.String("model_session_id", input.SessionID),
   384→		slog.String("transcript_path", input.SessionRef),
   385→	)
   386→
   387→	modelSessionID := input.SessionID
   388→	if modelSessionID == "" {
   389→		modelSessionID = unknownSessionID
   390→	}
   391→
   392→	// Get the Entire session ID, preferring the persisted value to handle midnight boundary
   393→	entireSessionID := currentSessionIDWithFallback(modelSessionID)
   394→
   395→	transcriptPath := input.SessionRef
   396→	if transcriptPath == "" || !fileExists(transcriptPath) {
   397→		return fmt.Errorf("transcript file not found or empty: %s", transcriptPath)
   398→	}
   399→
   400→	// Create session metadata folder using the entire session ID (preserves original date on resume)
   401→	// Use AbsPath to ensure we create at repo root, not relative to cwd
   402→	sessionDir := paths.SessionMetadataDirFromEntireID(entireSessionID)
   403→	sessionDirAbs, err := paths.AbsPath(sessionDir)
   404→	if err != nil {
   405→		sessionDirAbs = sessionDir // Fallback to relative
   406→	}
   407→	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
   408→		return fmt.Errorf("failed to create session directory: %w", err)
   409→	}
   410→
   411→	// Copy transcript
   412→	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
   413→	if err := copyFile(transcriptPath, logFile); err != nil {
   414→		return fmt.Errorf("failed to copy transcript: %w", err)
   415→	}
   416→	fmt.Fprintf(os.Stderr, "Copied transcript to: %s\n", sessionDir+"/"+paths.TranscriptFileName)
   417→
   418→	// Load session state to get transcript offset (for strategies that track it)
   419→	// This is used to only parse NEW transcript lines since the last checkpoint
   420→	var transcriptOffset int
   421→	sessionState, loadErr := strategy.LoadSessionState(entireSessionID)
   422→	if loadErr != nil {
   423→		fmt.Fprintf(os.Stderr, "Warning: failed to load session state: %v\n", loadErr)
   424→	}
   425→	if sessionState != nil {
   426→		transcriptOffset = sessionState.CondensedTranscriptLines
   427→		fmt.Fprintf(os.Stderr, "Session state found: parsing transcript from line %d\n", transcriptOffset)
   428→	}
   429→
   430→	// Parse transcript (optionally from offset for strategies that track transcript position)
   431→	// When transcriptOffset > 0, only parse NEW lines since the last checkpoint
   432→	var transcript []transcriptLine
   433→	var totalLines int
   434→	if transcriptOffset > 0 {
   435→		// Parse only NEW lines since last checkpoint
   436→		transcript, totalLines, err = parseTranscriptFromLine(transcriptPath, transcriptOffset)
   437→		if err != nil {
   438→			return fmt.Errorf("failed to parse transcript from line %d: %w", transcriptOffset, err)
   439→		}
   440→		fmt.Fprintf(os.Stderr, "Parsed %d new transcript lines (total: %d)\n", len(transcript), totalLines)
   441→	} else {
   442→		// First prompt or no session state - parse entire transcript
   443→		// Use parseTranscriptFromLine with offset 0 to also get totalLines
   444→		transcript, totalLines, err = parseTranscriptFromLine(transcriptPath, 0)
   445→		if err != nil {
   446→			return fmt.Errorf("failed to parse transcript: %w", err)
   447→		}
   448→	}
   449→
   450→	// Extract all prompts since last checkpoint for prompt file
   451→	allPrompts := extractUserPrompts(transcript)
   452→	promptFile := filepath.Join(sessionDirAbs, paths.PromptFileName)
   453→	promptContent := strings.Join(allPrompts, "\n\n---\n\n")
   454→	if err := os.WriteFile(promptFile, []byte(promptContent), 0o600); err != nil {
   455→		return fmt.Errorf("failed to write prompt file: %w", err)
   456→	}
   457→	fmt.Fprintf(os.Stderr, "Extracted %d prompt(s) to: %s\n", len(allPrompts), sessionDir+"/"+paths.PromptFileName)
   458→
   459→	// Extract summary
   460→	summaryFile := filepath.Join(sessionDirAbs, paths.SummaryFileName)
   461→	summary := extractLastAssistantMessage(transcript)
   462→	if err := os.WriteFile(summaryFile, []byte(summary), 0o600); err != nil {
   463→		return fmt.Errorf("failed to write summary file: %w", err)
   464→	}
   465→	fmt.Fprintf(os.Stderr, "Extracted summary to: %s\n", sessionDir+"/"+paths.SummaryFileName)
   466→
   467→	// Get modified files from transcript
   468→	modifiedFiles := extractModifiedFiles(transcript)
   469→
   470→	// Generate commit message from last user prompt
   471→	lastPrompt := ""
   472→	if len(allPrompts) > 0 {
   473→		lastPrompt = allPrompts[len(allPrompts)-1]
   474→	}
   475→	commitMessage := generateCommitMessage(lastPrompt)
   476→	fmt.Fprintf(os.Stderr, "Using commit message: %s\n", commitMessage)
   477→
   478→	// Get repo root for path conversion (not cwd, since Claude may be in a subdirectory)
   479→	// Using cwd would filter out files in sibling directories (paths starting with ..)
   480→	repoRoot, err := paths.RepoRoot()
   481→	if err != nil {
   482→		return fmt.Errorf("failed to get repo root: %w", err)
   483→	}
   484→
   485→	// Load pre-prompt state (captured on UserPromptSubmit)
   486→	preState, err := LoadPrePromptState(entireSessionID)
   487→	if err != nil {
   488→		fmt.Fprintf(os.Stderr, "Warning: failed to load pre-prompt state: %v\n", err)
   489→	}
   490→	if preState != nil {
   491→		fmt.Fprintf(os.Stderr, "Loaded pre-prompt state: %d pre-existing untracked files\n", len(preState.UntrackedFiles))
   492→	}
   493→
   494→	// Compute new files (files created during session)
   495→	newFiles, err := ComputeNewFiles(preState)
   496→	if err != nil {
   497→		fmt.Fprintf(os.Stderr, "Warning: failed to compute new files: %v\n", err)
   498→	}
   499→
   500→	// Compute deleted files (tracked files that were deleted)
   501→	deletedFiles, err := ComputeDeletedFiles()
   502→	if err != nil {
   503→		fmt.Fprintf(os.Stderr, "Warning: failed to compute deleted files: %v\n", err)
   504→	}
   505→
   506→	// Filter and normalize all paths (CLI responsibility)
   507→	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
   508→	relNewFiles := FilterAndNormalizePaths(newFiles, repoRoot)
   509→	relDeletedFiles := FilterAndNormalizePaths(deletedFiles, repoRoot)
   510→
   511→	// Check if there are any changes to commit
   512→	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
   513→	if totalChanges == 0 {
   514→		fmt.Fprintf(os.Stderr, "No files were modified during this session\n")
   515→		fmt.Fprintf(os.Stderr, "Skipping commit\n")
   516→		// Clean up state even when skipping
   517→		if err := CleanupPrePromptState(entireSessionID); err != nil {
   518→			fmt.Fprintf(os.Stderr, "Warning: failed to cleanup pre-prompt state: %v\n", err)
   519→		}
   520→		return nil
   521→	}
   522→
   523→	fmt.Fprintf(os.Stderr, "Files modified during session (%d):\n", len(relModifiedFiles))
   524→	for _, file := range relModifiedFiles {
   525→		fmt.Fprintf(os.Stderr, "  - %s\n", file)
   526→	}
   527→	if len(relNewFiles) > 0 {
   528→		fmt.Fprintf(os.Stderr, "New files created (%d):\n", len(relNewFiles))
   529→		for _, file := range relNewFiles {
   530→			fmt.Fprintf(os.Stderr, "  + %s\n", file)
   531→		}
   532→	}
   533→	if len(relDeletedFiles) > 0 {
   534→		fmt.Fprintf(os.Stderr, "Files deleted (%d):\n", len(relDeletedFiles))
   535→		for _, file := range relDeletedFiles {
   536→			fmt.Fprintf(os.Stderr, "  - %s\n", file)
   537→		}
   538→	}
   539→
   540→	// Create context file before saving changes
   541→	contextFile := filepath.Join(sessionDirAbs, paths.ContextFileName)
   542→	if err := createContextFileMinimal(contextFile, commitMessage, entireSessionID, promptFile, summaryFile, transcript); err != nil {
   543→		return fmt.Errorf("failed to create context file: %w", err)
   544→	}
   545→	fmt.Fprintf(os.Stderr, "Created context file: %s\n", sessionDir+"/"+paths.ContextFileName)
   546→
   547→	// Get git author from local/global config
   548→	author, err := GetGitAuthor()
   549→	if err != nil {
   550→		return fmt.Errorf("failed to get git author: %w", err)
   551→	}
   552→
   553→	// Get the configured strategy
   554→	strat := GetStrategy()
   555→
   556→	// Ensure strategy setup is in place (auto-installs git hook, gitignore, etc. if needed)
   557→	if err := strat.EnsureSetup(); err != nil {
   558→		fmt.Fprintf(os.Stderr, "Warning: failed to ensure strategy setup: %v\n", err)
   559→	}
   560→
   561→	// Get agent type from the currently executing hook agent (authoritative source)
   562→	var agentType agent.AgentType
   563→	if hookAgent, agentErr := GetCurrentHookAgent(); agentErr == nil {
   564→		agentType = hookAgent.Type()
   565→	}
   566→
   567→	// Get transcript position from pre-prompt state (captured at checkpoint start)
   568→	var transcriptIdentifierAtStart string
   569→	var transcriptLinesAtStart int
   570→	if preState != nil {
   571→		transcriptIdentifierAtStart = preState.LastTranscriptIdentifier
   572→		transcriptLinesAtStart = preState.LastTranscriptLineCount
   573→	}
   574→
   575→	// Calculate token usage for this checkpoint (Claude Code specific)
   576→	var tokenUsage *agent.TokenUsage
   577→	if transcriptPath != "" {
   578→		// Subagents are stored in a subagents/ directory next to the main transcript
   579→		subagentsDir := filepath.Join(filepath.Dir(transcriptPath), entireSessionID, "subagents")
   580→		usage, err := claudecode.CalculateTotalTokenUsage(transcriptPath, transcriptLinesAtStart, subagentsDir)
   581→		if err != nil {
   582→			fmt.Fprintf(os.Stderr, "Warning: failed to calculate token usage: %v\n", err)
   583→		} else {
   584→			tokenUsage = usage
   585→		}
   586→	}
   587→
   588→	// Build fully-populated save context and delegate to strategy
   589→	ctx := strategy.SaveContext{
   590→		SessionID:                   entireSessionID,
   591→		ModifiedFiles:               relModifiedFiles,
   592→		NewFiles:                    relNewFiles,
   593→		DeletedFiles:                relDeletedFiles,
   594→		MetadataDir:                 sessionDir,
   595→		MetadataDirAbs:              sessionDirAbs,
   596→		CommitMessage:               commitMessage,
   597→		TranscriptPath:              transcriptPath,
   598→		AuthorName:                  author.Name,
   599→		AuthorEmail:                 author.Email,
   600→		AgentType:                   agentType,
   601→		TranscriptIdentifierAtStart: transcriptIdentifierAtStart,
   602→		TranscriptLinesAtStart:      transcriptLinesAtStart,
   603→		TokenUsage:                  tokenUsage,
   604→	}
   605→
   606→	if err := strat.SaveChanges(ctx); err != nil {
   607→		return fmt.Errorf("failed to save changes: %w", err)
   608→	}
   609→
   610→	// Update session state with new transcript position for strategies that create
   611→	// commits on the active branch (auto-commit strategy). This prevents parsing old transcript
   612→	// lines on subsequent checkpoints.
   613→	// Note: Shadow strategy doesn't create commits on the active branch, so its
   614→	// checkpoints don't "consume" the transcript in the same way. Shadow should
   615→	// continue parsing the full transcript to capture all files touched in the session.
   616→	if strat.Name() == strategy.StrategyNameAutoCommit {
   617→		// Create session state lazily if it doesn't exist (backward compat for resumed sessions
   618→		// or if InitializeSession was never called/failed)
   619→		if sessionState == nil {
   620→			sessionState = &strategy.SessionState{
   621→				SessionID: entireSessionID,
   622→			}
   623→		}
   624→		sessionState.CondensedTranscriptLines = totalLines
   625→		sessionState.CheckpointCount++
   626→		if updateErr := strategy.SaveSessionState(sessionState); updateErr != nil {
   627→			fmt.Fprintf(os.Stderr, "Warning: failed to update session state: %v\n", updateErr)
   628→		} else {
   629→			fmt.Fprintf(os.Stderr, "Updated session state: transcript position=%d, checkpoint=%d\n",
   630→				totalLines, sessionState.CheckpointCount)
   631→		}
   632→	}
   633→
   634→	// Clean up pre-prompt state (CLI responsibility)
   635→	if err := CleanupPrePromptState(entireSessionID); err != nil {
   636→		fmt.Fprintf(os.Stderr, "Warning: failed to cleanup pre-prompt state: %v\n", err)
   637→	}
   638→
   639→	return nil
   640→}
