   642→// handleClaudeCodePostTodo handles the PostToolUse[TodoWrite] hook for subagent checkpoints.
   643→// Creates a checkpoint if we're in a subagent context (active pre-task file exists).
   644→// Skips silently if not in subagent context (main agent).
   645→func handleClaudeCodePostTodo() error {
   646→	input, err := parseSubagentCheckpointHookInput(os.Stdin)
   647→	if err != nil {
   648→		return fmt.Errorf("failed to parse PostToolUse[TodoWrite] input: %w", err)
   649→	}
   650→
   651→	// Get agent for logging context
   652→	ag, err := GetCurrentHookAgent()
   653→	if err != nil {
   654→		return fmt.Errorf("failed to get agent: %w", err)
   655→	}
   656→
   657→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
   658→	logging.Info(logCtx, "post-todo",
   659→		slog.String("hook", "post-todo"),
   660→		slog.String("hook_type", "subagent"),
   661→		slog.String("model_session_id", input.SessionID),
   662→		slog.String("transcript_path", input.TranscriptPath),
   663→		slog.String("tool_use_id", input.ToolUseID),
   664→	)
   665→
   666→	// Check if we're in a subagent context by looking for an active pre-task file
   667→	taskToolUseID, found := FindActivePreTaskFile()
   668→	if !found {
   669→		// Not in subagent context - this is a main agent TodoWrite, skip
   670→		return nil
   671→	}
   672→
   673→	// Skip on default branch to avoid polluting main/master history
   674→	if skip, branchName := ShouldSkipOnDefaultBranch(); skip {
   675→		fmt.Fprintf(os.Stderr, "Entire: skipping incremental checkpoint on branch '%s'\n", branchName)
   676→		return nil
   677→	}
   678→
   679→	// Detect file changes since last checkpoint
   680→	modified, newFiles, deleted, err := DetectChangedFiles()
   681→	if err != nil {
   682→		fmt.Fprintf(os.Stderr, "Warning: failed to detect changed files: %v\n", err)
   683→		return nil
   684→	}
   685→
   686→	// If no file changes, skip creating a checkpoint
   687→	if len(modified) == 0 && len(newFiles) == 0 && len(deleted) == 0 {
   688→		fmt.Fprintf(os.Stderr, "[entire] No file changes detected, skipping incremental checkpoint\n")
   689→		return nil
   690→	}
   691→
   692→	// Get git author
   693→	author, err := GetGitAuthor()
   694→	if err != nil {
   695→		fmt.Fprintf(os.Stderr, "Warning: failed to get git author: %v\n", err)
   696→		return nil
   697→	}
   698→
   699→	// Get the active strategy
   700→	strat := GetStrategy()
   701→
   702→	// Ensure strategy setup is complete
   703→	if err := strat.EnsureSetup(); err != nil {
   704→		fmt.Fprintf(os.Stderr, "Warning: failed to ensure strategy setup: %v\n", err)
   705→		return nil
   706→	}
   707→
   708→	// Get the session ID from the transcript path or input, then transform to Entire session ID
   709→	sessionID := paths.ExtractSessionIDFromTranscriptPath(input.TranscriptPath)
   710→	if sessionID == "" {
   711→		sessionID = input.SessionID
   712→	}
   713→	entireSessionID := currentSessionIDWithFallback(sessionID)
   714→
   715→	// Get next checkpoint sequence
   716→	seq := GetNextCheckpointSequence(entireSessionID, taskToolUseID)
   717→
   718→	// Extract the todo content from the tool_input.
   719→	// PostToolUse receives the NEW todo list where the just-completed work is
   720→	// marked as "completed". The last completed item is the work that was just done.
   721→	todoContent := ExtractLastCompletedTodoFromToolInput(input.ToolInput)
   722→	if todoContent == "" {
   723→		// No completed items - this is likely the first TodoWrite (planning phase).
   724→		// Check if there are any todos at all to avoid duplicate messages.
   725→		todoCount := CountTodosFromToolInput(input.ToolInput)
   726→		if todoCount > 0 {
   727→			// Use "Planning: N todos" format for the first TodoWrite
   728→			todoContent = fmt.Sprintf("Planning: %d todos", todoCount)
   729→		}
   730→		// If todoCount == 0, todoContent remains empty and FormatIncrementalMessage
   731→		// will fall back to "Checkpoint #N" format
   732→	}
   733→
   734→	// Get agent type from the currently executing hook agent (authoritative source)
   735→	var agentType agent.AgentType
   736→	if hookAgent, agentErr := GetCurrentHookAgent(); agentErr == nil {
   737→		agentType = hookAgent.Type()
   738→	}
   739→
   740→	// Build incremental checkpoint context
   741→	ctx := strategy.TaskCheckpointContext{
   742→		SessionID:           entireSessionID,
   743→		ToolUseID:           taskToolUseID,
   744→		ModifiedFiles:       modified,
   745→		NewFiles:            newFiles,
   746→		DeletedFiles:        deleted,
   747→		TranscriptPath:      input.TranscriptPath,
   748→		AuthorName:          author.Name,
   749→		AuthorEmail:         author.Email,
   750→		IsIncremental:       true,
   751→		IncrementalSequence: seq,
   752→		IncrementalType:     input.ToolName,
   753→		IncrementalData:     input.ToolInput,
   754→		TodoContent:         todoContent,
   755→		AgentType:           agentType,
   756→	}
   757→
   758→	// Save incremental checkpoint
   759→	if err := strat.SaveTaskCheckpoint(ctx); err != nil {
   760→		fmt.Fprintf(os.Stderr, "Warning: failed to save incremental checkpoint: %v\n", err)
   761→		return nil
   762→	}
   763→
   764→	fmt.Fprintf(os.Stderr, "[entire] Created incremental checkpoint #%d for %s (task: %s)\n",
   765→		seq, input.ToolName, taskToolUseID[:min(12, len(taskToolUseID))])
   766→	return nil
   767→}
