func ComputeFileChanges(preState *PrePromptState) (newFiles, deletedFiles []string, err error) {
	if preState == nil {
		return nil, nil, nil
	}

	repo, err := openRepository()
	if err != nil {
		return nil, nil, err
	}

	worktree, err := repo.Worktree()
	if err != nil {
		return nil, nil, err
	}

