// collectUntrackedFiles collects untracked files using worktree.Status().
// This respects .gitignore and is much faster than walking the filesystem.
// The base tree already contains all tracked files, so we only need untracked files.
func collectUntrackedFiles(repo *git.Repository) ([]string, error) {
	worktree, err := repo.Worktree()
	if err != nil {
		return nil, fmt.Errorf("failed to get worktree: %w", err)
	}

	status, err := worktree.Status()
	if err != nil {
		return nil, fmt.Errorf("failed to get worktree status: %w", err)
	}

	var files []string
	for file, st := range status {
		// Only include untracked files (not ignored by .gitignore)
		if st.Worktree == git.Untracked {
			// Skip .entire directory
			if paths.IsInfrastructurePath(file) {
				continue
			}
			files = append(files, file)
		}
	}

	return files, nil
}

